# ── SESSION STATE ─────────────────────────────────────────────────────────
def init():
    defaults = {"phase":"start","questions":[],"idx":0,"answers":{},"exam_start":None,"num_q":40}
    for k,v in defaults.items():
        if k not in st.session_state:
            st.session_state[k] = v

def reset():
    for k in ["phase","questions","idx","answers","exam_start"]:
        if k in st.session_state:
            del st.session_state[k]
    st.session_state["num_q"] = 40

init()

# ── HEADER ────────────────────────────────────────────────────────────────
st.markdown(f"""
<div class="exam-header">
    <h1>📋 CBAP® Exam Simulator</h1>
    <p>Chapter 2 — Business Analysis Key Concepts · BABOK® v3 · {len(ALL_QUESTIONS)} Questions · Mixed Difficulty</p>
</div>""", unsafe_allow_html=True)

# ══ START SCREEN ══════════════════════════════════════════════════════════
if st.session_state.phase == "start":
    c1,c2,c3 = st.columns([1,2,1])
    with c2:
        st.markdown(f"""
        <div style='background:rgba(255,255,255,0.05);border:1px solid rgba(201,168,76,0.3);
                    border-radius:12px;padding:1.8rem;margin-bottom:1.5rem;
                    font-family:"Source Sans 3",sans-serif;color:#c8d4e8;line-height:1.7'>
            <b style='color:#c9a84c;font-size:1.05rem'>📌 Exam Rules</b><br><br>
            • {len(ALL_QUESTIONS)} questions available — Chapter 2 BABOK® v3<br>
            • Topics: BACCM · Requirements Classification · Stakeholders · Requirements vs Designs<br>
            • Difficulty: Foundational · Intermediate · Advanced · Expert<br>
            • Navigate freely and change answers before finishing<br>
            • <b style='color:#f0d080'>No feedback during the exam</b> — full review shown at the end<br>
            • Passing score: <b style='color:#f0d080'>70%</b>
        </div>""", unsafe_allow_html=True)
        num = st.slider("Number of questions", 5, len(ALL_QUESTIONS), 40, 1)
        st.session_state.num_q = num
        if st.button("🚀  Start Exam", use_container_width=True):
            pool = ALL_QUESTIONS.copy(); random.shuffle(pool)
            st.session_state.questions  = pool[:num]
            st.session_state.idx        = 0
            st.session_state.answers    = {}
            st.session_state.exam_start = time.time()
            st.session_state.phase      = "exam"
            st.rerun()

# ══ RESULTS SCREEN ════════════════════════════════════════════════════════
elif st.session_state.phase == "results":
    qs      = st.session_state.questions
    answers = st.session_state.answers
    total   = len(qs)
    correct = sum(1 for i,q in enumerate(qs) if answers.get(i)==q["answer"])
    pct     = round(correct/total*100)
    passed  = pct >= 70
    elapsed = int(time.time()-(st.session_state.exam_start or time.time()))
    mins,secs = divmod(elapsed,60)

    c1,c2,c3 = st.columns([1,3,1])
    with c2:
        verdict = "✅ PASSED" if passed else "❌ NOT PASSED"
        vclass  = "passed" if passed else "failed"
        st.markdown(f"""
        <div class="score-card">
            <div class="score-big">{pct}%</div>
            <div class="score-label">{correct} correct out of {total} questions</div>
            <div class="score-verdict {vclass}">{verdict}</div>
        </div>""", unsafe_allow_html=True)
        st.markdown(f"""
        <div class="stats-row">
            <div class="stat-box"><div class="stat-num">{correct}</div><div class="stat-lbl">Correct</div></div>
            <div class="stat-box"><div class="stat-num">{total-correct}</div><div class="stat-lbl">Incorrect</div></div>
            <div class="stat-box"><div class="stat-num">{mins}:{secs:02d}</div><div class="stat-lbl">Total Time</div></div>
            <div class="stat-box"><div class="stat-num">{pct}%</div><div class="stat-lbl">Score</div></div>
        </div>""", unsafe_allow_html=True)

        levels = ["Foundational","Intermediate","Advanced","Expert"]
        rows = ""
        for lvl in levels:
            lvl_qs  = [(i,q) for i,q in enumerate(qs) if lvl in q["chapter"]]
            if not lvl_qs: continue
            lvl_ok  = sum(1 for i,q in lvl_qs if answers.get(i)==q["answer"])
            lvl_tot = len(lvl_qs)
            lvl_pct = round(lvl_ok/lvl_tot*100)
            col = "#6fe4a4" if lvl_pct>=70 else ("#f0d080" if lvl_pct>=50 else "#f4a0a0")
            rows += f"<tr><td style='padding:.5rem .8rem;color:#f4f1eb;font-weight:600'>{lvl}</td><td style='padding:.5rem .8rem;color:#c8d4e8;text-align:center'>{lvl_tot}</td><td style='padding:.5rem .8rem;color:#6fe4a4;text-align:center'>{lvl_ok}</td><td style='padding:.5rem .8rem;color:#f4a0a0;text-align:center'>{lvl_tot-lvl_ok}</td><td style='padding:.5rem .8rem;text-align:center;color:{col};font-weight:700'>{lvl_pct}%</td></tr>"
        st.markdown(f"""
        <div style='margin:1.5rem 0;background:rgba(255,255,255,0.04);border:1px solid rgba(201,168,76,0.2);border-radius:10px;overflow:hidden;font-family:"Source Sans 3",sans-serif'>
            <div style='padding:.7rem 1rem;background:rgba(201,168,76,0.1);color:#c9a84c;font-size:.8rem;font-weight:600;letter-spacing:1.5px;text-transform:uppercase'>Performance by Difficulty</div>
            <table style='width:100%;border-collapse:collapse'>
                <thead><tr style='border-bottom:1px solid rgba(255,255,255,0.08)'>
                    <th style='padding:.5rem .8rem;color:#6b7a99;font-weight:600;text-align:left;font-size:.8rem'>Level</th>
                    <th style='padding:.5rem .8rem;color:#6b7a99;text-align:center;font-size:.8rem'>Total</th>
                    <th style='padding:.5rem .8rem;color:#6b7a99;text-align:center;font-size:.8rem'>✅ Correct</th>
                    <th style='padding:.5rem .8rem;color:#6b7a99;text-align:center;font-size:.8rem'>❌ Wrong</th>
                    <th style='padding:.5rem .8rem;color:#6b7a99;text-align:center;font-size:.8rem'>Score</th>
                </tr></thead>
                <tbody>{rows}</tbody>
            </table>
        </div>""", unsafe_allow_html=True)

        st.markdown("<br>", unsafe_allow_html=True)
        st.markdown("<div style='font-family:\"Source Sans 3\",sans-serif;color:#c9a84c;font-size:1rem;font-weight:600;margin-bottom:1rem'>📋 Question Review</div>", unsafe_allow_html=True)
        for i,q in enumerate(qs):
            user_ans    = answers.get(i,"Not answered")
            correct_ans = q["answer"]
            is_correct  = user_ans == correct_ans
            icon  = "✅" if is_correct else "❌"
            bg    = "rgba(30,124,74,0.1)" if is_correct else "rgba(155,35,53,0.1)"
            border= "#1e7c4a" if is_correct else "#9b2335"
            detail = ""
            if not is_correct:
                detail = f"<div style='margin-top:.5rem;color:#f4a0a0;font-size:.9rem'>Your answer: {user_ans}</div><div style='margin-top:.3rem;color:#6fe4a4;font-size:.9rem'>Correct answer: {correct_ans}</div><div style='margin-top:.5rem;color:#c8d4e8;font-size:.88rem'>💡 {q['explanation']}</div>"
            st.markdown(f"""
            <div style='margin-bottom:.8rem;padding:.9rem 1.1rem;background:{bg};border-left:3px solid {border};border-radius:8px;font-family:"Source Sans 3",sans-serif'>
                <div style='color:#f4f1eb;font-size:.92rem'>{icon} <b>Q{i+1}.</b> {q['question']}</div>
                {detail}
            </div>""", unsafe_allow_html=True)

        st.markdown("<br>", unsafe_allow_html=True)
        if st.button("🔄  New Exam", use_container_width=True):
            reset(); st.rerun()

# ══ EXAM SCREEN ═══════════════════════════════════════════════════════════
elif st.session_state.phase == "exam":
    if HAS_AUTOREFRESH:
        st_autorefresh(interval=1000, limit=None, key="timer_refresh")

    qs    = st.session_state.questions
    total = len(qs)
    idx   = st.session_state.idx
    q     = qs[idx]

    elapsed = int(time.time()-(st.session_state.exam_start or time.time()))
    em,es = divmod(elapsed,60)
    answered_count = sum(1 for a in st.session_state.answers.values() if a)

    col_prog, col_timer = st.columns([3,1])
    with col_prog:
        pct = int(answered_count/total*100)
        st.markdown(f"""
        <div style='font-family:"Source Sans 3",sans-serif;color:#8090aa;font-size:.85rem'>
            Question {idx+1} of {total} &nbsp;|&nbsp; {answered_count}/{total} answered
        </div>
        <div class="progress-container"><div class="progress-bar" style="width:{pct}%"></div></div>""", unsafe_allow_html=True)
    with col_timer:
        st.markdown(f"<div style='text-align:right;font-family:\"Source Sans 3\",sans-serif;font-size:1rem;color:#f0d080;padding-top:.3rem'>⏱ {em:02d}:{es:02d}</div>", unsafe_allow_html=True)

    is_answered = idx in st.session_state.answers
    answered_badge = " <span style='background:rgba(201,168,76,0.2);color:#f0d080;font-size:.72rem;padding:2px 8px;border-radius:10px;margin-left:6px;font-family:Source Sans 3,sans-serif'>answered</span>" if is_answered else ""
    st.markdown(f"""
    <div class="q-card">
        <div class="q-number">Question {idx+1}{answered_badge}</div>
        <div class="q-chapter">{q["chapter"].split("|")[0].strip()}</div>
        <p class="q-text">{q["question"]}</p>
    </div>""", unsafe_allow_html=True)

    current_answer = st.session_state.answers.get(idx, None)
    letter_options = ["A","B","C","D"]
    current_letter = current_answer[0] if current_answer else None
    try:
        default_idx = letter_options.index(current_letter) if current_letter else None
    except ValueError:
        default_idx = None

    chosen_letter = st.radio("Select your answer:", letter_options, index=default_idx, horizontal=True, key=f"radio_{idx}")

    for opt in q["options"]:
        st.write(opt)

    st.markdown("<br>", unsafe_allow_html=True)
    c1,c2,c3,c4 = st.columns([1,1,1,1])
    with c1:
        if idx > 0:
            if st.button("⬅ Previous", key=f"prev_{idx}"):
                if chosen_letter:
                    lmap = {o[0]:o for o in q["options"]}
                    st.session_state.answers[idx] = lmap[chosen_letter]
                st.session_state.idx = idx-1
                st.rerun()
    with c2:
        label = "Save & Next ➡" if idx < total-1 else "Save Answer"
        if st.button(label, key=f"next_{idx}"):
            if chosen_letter:
                lmap = {o[0]:o for o in q["options"]}
                st.session_state.answers[idx] = lmap[chosen_letter]
            if idx < total-1:
                st.session_state.idx = idx+1
            st.rerun()
    with c3:
        if st.button("🏁 Finish Exam", key=f"finish_{idx}"):
            if chosen_letter:
                lmap = {o[0]:o for o in q["options"]}
                st.session_state.answers[idx] = lmap[chosen_letter]
            st.session_state.phase = "results"
            st.rerun()
    with c4:
        if st.button("🔄 Restart", key=f"restart_{idx}"):
            reset(); st.rerun()

    st.markdown("<br><div style='font-family:\"Source Sans 3\",sans-serif;color:#6b7a99;font-size:.8rem;margin-bottom:.4rem'>Jump to question:</div>", unsafe_allow_html=True)
    cols_per_row = 20
    nav_rows = [list(range(total))[i:i+cols_per_row] for i in range(0,total,cols_per_row)]
    for row in nav_rows:
        nav_cols = st.columns(len(row))
        for j,q_idx in enumerate(row):
            with nav_cols[j]:
                is_ans = q_idx in st.session_state.answers
                marker = "●" if is_ans else "○"
                if st.button(f"{marker}{q_idx+1}", key=f"nav_{q_idx}"):
                    if chosen_letter:
                        lmap = {o[0]:o for o in q["options"]}
                        st.session_state.answers[idx] = lmap[chosen_letter]
                    st.session_state.idx = q_idx
                    st.rerun()
